-- Di lab, batas harian dijaga kode service Go; di widget ini, view dan trigger memerankannya
CREATE VIEW keluar_hari_ini AS
  SELECT p.buku_id, -SUM(p.jumlah) AS keluar
  FROM posting p JOIN jurnal j ON j.id = p.jurnal_id
  WHERE p.jumlah < 0 AND j.jenis = 'transfer' AND j.dibuat >= '2026-11-20 00:00'
  GROUP BY p.buku_id;
CREATE TRIGGER batas_harian BEFORE INSERT ON posting
  WHEN NEW.jumlah < 0 AND (SELECT jenis FROM jurnal WHERE id = NEW.jurnal_id) = 'transfer'
   AND COALESCE((SELECT keluar FROM keluar_hari_ini WHERE buku_id = NEW.buku_id), 0) - NEW.jumlah > 500000
BEGIN
  SELECT RAISE(ABORT, '422 batas-harian: kiriman hari ini lebih dari Rp500.000');
END;
